function Icon({ name }) {
  if (iconsFilled[name]) {
    return (
      <svg className="is-filled" viewBox="0 0 26 26" aria-hidden="true">
        {iconsFilled[name]}
      </svg>
    );
  }
  if (icons36[name]) {
    return (
      <svg className="is-36" viewBox="0 0 36 36" aria-hidden="true">
        {icons36[name]}
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true">
      {icons[name]}
    </svg>
  );
}

function CardGrid({ items, variant }) {
  const [active, setActive] = useState(0);

  return (
    <ul className={`sd-cards sd-cards-${variant}`}>
      {items.map((item, index) => (
        <li
          key={item.title}
          className={index === active ? "sd-card is-active" : "sd-card"}
          tabIndex={0}
          onMouseEnter={() => setActive(index)}
          onFocus={() => setActive(index)}
        >
          <span className={`sd-icon${item.tone ? ` is-${item.tone}` : ""}`}>
            {/* iconSrc: a supplied icon image, shown exactly as designed */}
            {item.iconSrc ? <img loading="lazy" decoding="async" src={item.iconSrc} alt="" /> : <Icon name={item.icon} />}
          </span>
          <h3>{item.title}</h3>
          <p>{item.text}</p>
        </li>
      ))}
    </ul>
  );
}

/* one template for every service detail page; content lives in serviceDetails.js */
function ServiceDetail({ page }) {
  return (
    <div className="sd-page">
      {page.wavesHero && (
        <img loading="lazy" decoding="async" className="sd-waves-hero" src={page.wavesHero} alt="" aria-hidden="true" />
      )}
      {page.wavesBody && (
        <div className="sd-waves-body" aria-hidden="true">
          <img loading="lazy" decoding="async" src={page.wavesBody} alt="" />
        </div>
      )}

      <section className="sd-hero">
        <p className="sd-kicker">{page.kicker}</p>
        {/* titleParts: one line of [text, isAccent] pieces; otherwise title + accent on line two */}
        {page.titleParts ? (
          <h1>
            {page.titleParts.map(([text, accent]) =>
              accent ? (
                <span key={text} className="is-orange">
                  {text}
                </span>
              ) : (
                text
              )
            )}
          </h1>
        ) : (
          <h1>
            {page.title}
            {page.titleAccentInline && (
              <>
                {" "}
                <span className="is-orange">{page.titleAccentInline}</span>
              </>
            )}
            <br />
            <span className={page.titleAccentTone === "orange" ? "is-orange" : undefined}>
              {page.titleAccent}
            </span>
          </h1>
        )}
        <p className="sd-lead" style={{ maxWidth: page.leadWidth }}>
          {page.lead}
        </p>
        <div className="sd-actions">
          <a href="#contact" className="sd-btn sd-btn-primary">
            Start a project
          </a>
          <a href={`#${page.slug}-capabilities`} className="sd-btn sd-btn-ghost">
            Explore capabilities
            <svg viewBox="0 0 20 20" aria-hidden="true">
              <path d="M10 4v12M5 11l5 5 5-5" />
            </svg>
          </a>
        </div>
        <img loading="lazy" decoding="async"
          className="sd-hero-art"
          src={page.art}
          width={page.artSize?.[0] ?? 1536}
          height={page.artSize?.[1] ?? 1024}
          style={page.artStyle}
          alt={page.artAlt}
        />
      </section>

      <section className="sd-block sd-capabilities" id={`${page.slug}-capabilities`}>
        <div className="sd-head">
          <div>
            <p className="sd-label">What we do</p>
            <h2>
              {page.whatWeDo.layout === "accent-first" ? (
                <>
                  <span>{page.whatWeDo.accent}</span>
                  <br />
                  {page.whatWeDo.title}
                </>
              ) : page.whatWeDo.layout === "accent-inline" ? (
                <>
                  {page.whatWeDo.title}
                  <br />
                  {page.whatWeDo.lineTwo} <span>{page.whatWeDo.accent}</span>
                </>
              ) : page.whatWeDo.layout === "accent-after" ? (
                <>
                  {page.whatWeDo.title}
                  <br />
                  <span>{page.whatWeDo.accent}</span>
                </>
              ) : (
                <>
                  {page.whatWeDo.title}
                  <br />
                  for <span>{page.whatWeDo.accent}</span>
                </>
              )}
            </h2>
          </div>
          <p className="sd-head-text" style={page.whatWeDo.textStyle}>
            {page.whatWeDo.text}
          </p>
        </div>
        <CardGrid items={page.capabilities} variant="dark" />
      </section>

      <section className="sd-problems">
        <div className="sd-block">
          <div className="sd-head">
            <div>
              <p className="sd-label">Common problems</p>
              <h2>
                Problems we <span>solve</span>.
              </h2>
            </div>
            <p className="sd-head-text">{page.problemsText}</p>
          </div>
          <CardGrid items={page.problems} variant="orange" />
        </div>
      </section>

      <section
        className={`sd-block sd-industries${page.industryIconsLight ? " is-light-icons" : ""}${
          page.industryCompact ? " is-compact" : ""
        }`}
      >
        <div className="sd-head is-row">
          <div>
            <p className="sd-label">Where it fits</p>
            <h2 style={{ maxWidth: page.industriesTitleWidth }}>
              {page.industriesTitle}{" "}
              <span>{page.industriesAccent || "every industry."}</span>
            </h2>
          </div>
          <a className="sd-more" href="#industries" style={page.industriesLinkStyle}>
            See all industries
            <svg className="sd-more-arrow" viewBox="118.7 2.5 10.25 6.75" aria-hidden="true">
              <path d="M118.713 6.46V5.284h8.155l-2.016-2.016.714-.728 3.339 3.339-3.339 3.339-.714-.728 2.03-2.03h-8.169Z" />
            </svg>
          </a>
        </div>
        <ul className="sd-industry-grid" style={page.industriesGridStyle}>
          {page.industries.map((item) => (
            <li className="sd-industry" key={item.title}>
              <div
                className={`sd-industry-photo${item.photo ? " has-photo" : ""}`}
                style={item.photoBg ? { background: item.photoBg } : undefined}
              >
                {item.photo ? (
                  <img src={item.photo} alt="" loading="lazy" />
                ) : (
                  <Icon name={item.icon} />
                )}
              </div>
              <div className="sd-industry-body">
                <span className={`sd-icon is-small${item.tone ? ` is-${item.tone}` : ""}`}>
                  <Icon name={item.icon} />
                </span>
                <h3>{item.title}</h3>
                <p style={{ maxWidth: page.industriesTextWidth }}>{item.text}</p>
              </div>
            </li>
          ))}
        </ul>
      </section>

      <ServicePricing slug={page.slug} />
    </div>
  );
}

export default ServiceDetail;
